      "fTerm": "MACHINES, DEVICES, OR PROCESSES FOR GRINDING OR POLISHING (by electro-erosion <b>B23H</b>; abrasive or related blasting <b>B24C</b>;  electrolytic etching or polishing <b>C25F 3/00</b>); DRESSING OR CONDITIONING OF ABRADING SURFACES; FEEDING OF GRINDING, POLISHING, OR LAPPING AGENTS<b>[2]</b><br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>In this subclass, the following term is used with the meaning indicated:<b>[4]</b><ul type=\"\"disc\"\"><li>&quot;polishing&quot; means the smoothing of a surface, i.e. a surface improvement but no improvement of the dimensional accuracy as would occur in a &quot;grinding&quot; operation.</li></ul></li><li>Attention is drawn to Notes (1) and (2) following the title of subclass <b>B23F</b>.</li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">GRINDING OR POLISHING PROCESSES NOT PARTICULAR TO SPECIFIC MACHINES, DEVICES OR WORK</td><td><b>1/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">GRINDING; GENERAL FEATURES OF GRINDING, POLISHING, OR FINISHING</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Grinding of surfaces with simple shapes</td><td><b>5/00</b>, <b>7/00</b>, <b>9/00</b>, <b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Grinding of surfaces of special shape</td><td><b>3/00</b>, <b>13/00-19/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Grinding or polishing using abrasive belts</td><td><b>21/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Portable machines</td><td><b>23/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Other machines</td><td><b>25/00</b>, <b>27/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Component parts</td><td><b>41/00-47/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Measuring, indicating, controlling; Safety</td><td><b>49/00</b>, <b>51/00</b>; <b>55/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Dressing or conditioning of grinding tools; Feeding or applying grinding, polishing or lapping agents</td><td><b>53/00</b>; <b>57/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">POLISHING OR FINISHING</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Polishing, burnishing</td><td><b>29/00</b>, <b>39/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">by tumbling</td><td><b>31/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Honing, superfinishing</td><td><b>33/00</b>, <b>35/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Lapping</td><td><b>37/00</b></td></p></tr></p></tr></table>",
      "childFlag": 0,
